CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issuer text NOT NULL,subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(issuer,subject));
CREATE TABLE platform_admins(identity_id uuid PRIMARY KEY REFERENCES identities(id) ON DELETE RESTRICT);
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),authz_version bigint NOT NULL DEFAULT 1 CHECK(authz_version>=1));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,api_audience text NOT NULL UNIQUE,service_client_id text NOT NULL UNIQUE,service_subject text NOT NULL UNIQUE);
CREATE TABLE tenant_products(tenant_id uuid NOT NULL REFERENCES tenants(id),product_id uuid NOT NULL REFERENCES products(id),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),PRIMARY KEY(tenant_id,product_id));
CREATE TABLE memberships(tenant_id uuid NOT NULL REFERENCES tenants(id),identity_id uuid NOT NULL REFERENCES identities(id),status text NOT NULL CHECK(status IN ('active','suspended','removed')),is_owner boolean NOT NULL DEFAULT false,PRIMARY KEY(tenant_id,identity_id));
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),name text NOT NULL CHECK(name ~ '^[a-z0-9-]+:[a-z0-9-]+:[a-z0-9-]+$'),risk text NOT NULL CHECK(risk IN ('routine','critical')),UNIQUE(product_id,name),UNIQUE(id,product_id));
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,product_id uuid NOT NULL,name text NOT NULL,FOREIGN KEY(tenant_id,product_id) REFERENCES tenant_products(tenant_id,product_id),UNIQUE(tenant_id,product_id,name),UNIQUE(id,tenant_id,product_id));
CREATE TABLE role_permissions(tenant_id uuid NOT NULL,product_id uuid NOT NULL,role_id uuid NOT NULL,permission_id uuid NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id,tenant_id,product_id) REFERENCES roles(id,tenant_id,product_id),FOREIGN KEY(permission_id,product_id) REFERENCES permissions(id,product_id));
CREATE TABLE role_assignments(tenant_id uuid NOT NULL,identity_id uuid NOT NULL,product_id uuid NOT NULL,role_id uuid NOT NULL,PRIMARY KEY(tenant_id,identity_id,product_id,role_id),FOREIGN KEY(tenant_id,identity_id) REFERENCES memberships(tenant_id,identity_id),FOREIGN KEY(tenant_id,product_id) REFERENCES tenant_products(tenant_id,product_id),FOREIGN KEY(role_id,tenant_id,product_id) REFERENCES roles(id,tenant_id,product_id));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),actor_id uuid REFERENCES identities(id),event_type text NOT NULL,target_id uuid,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_id uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version bigint NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,UNIQUE(aggregate_type,aggregate_id,aggregate_version));
